import{_ as s,o as n,c as e,a5 as p}from"./chunks/framework.CXroN2RO.js";const u=JSON.parse('{"title":"判断ガイド: C++の選択 — テンプレートか仮想関数か/値渡しか参照渡しか/unique_ptrかshared_ptrか/配列かvectorか/構造体かクラスか","description":"","frontmatter":{"title":"判断ガイド: C++の選択 — テンプレートか仮想関数か/値渡しか参照渡しか/unique_ptrかshared_ptrか/配列かvectorか/構造体かクラスか","study":{"source":"C++ Wiki","kind":"本文","status":"既存原稿","summary":"テンプレートの明示的実体化をライブラリから提供することもできます。ただし、それもC++ ABI・型定義・ビルド条件の互換性が必要です。処理系や言語をまたぐ公開APIでは、C ABIの関数と明示したデータ/所有権の契約を検討します。"}},"headers":[],"relativePath":"design/decisions/cpp-choices.md","filePath":"design/decisions/cpp-choices.md"}'),t={name:"design/decisions/cpp-choices.md"};function i(l,a,r,c,o,d){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="判断ガイド-c-の選択-—-テンプレートか仮想関数か-値渡しか参照渡しか-unique-ptrかshared-ptrか-配列かvectorか-構造体かクラスか" tabindex="-1">判断ガイド: C++の選択 — テンプレートか仮想関数か/値渡しか参照渡しか/unique_ptrかshared_ptrか/配列かvectorか/構造体かクラスか <a class="header-anchor" href="#判断ガイド-c-の選択-—-テンプレートか仮想関数か-値渡しか参照渡しか-unique-ptrかshared-ptrか-配列かvectorか-構造体かクラスか" aria-label="Permalink to &quot;判断ガイド: C++の選択 — テンプレートか仮想関数か/値渡しか参照渡しか/unique_ptrかshared_ptrか/配列かvectorか/構造体かクラスか&quot;">​</a></h1><h2 id="_1-テンプレートか仮想関数か" tabindex="-1">1. テンプレートか仮想関数か <a class="header-anchor" href="#_1-テンプレートか仮想関数か" aria-label="Permalink to &quot;1. テンプレートか仮想関数か&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Q1. 型は実行時に混ざる・切り替わるか?(vector&lt;Base*&gt;に入れる/実行中に差し替え)</span></span>
<span class="line"><span>    → はい ──&gt; 仮想関数(コンパイル時多態では表現できない)</span></span>
<span class="line"><span>Q2. 型はコンパイル時に決まるか?</span></span>
<span class="line"><span>    → はい ──&gt; テンプレート(実行時コストゼロ、型ごとに最適コード)</span></span>
<span class="line"><span>Q3. どちらでも書ける場合の追加考慮:</span></span>
<span class="line"><span>    ・ビルド時間/コードサイズが厳しい → 仮想関数寄り</span></span>
<span class="line"><span>    ・ホットループの内側/インライン化が効いてほしい → テンプレート寄り</span></span>
<span class="line"><span>    ・ABI境界(DLL/モジュール)を越える → ABI契約を先に確認。仮想関数でも自動的に安全にはならない</span></span>
<span class="line"><span>    ・エラーメッセージ・書きやすさ重視のチーム → 仮想関数寄り(conceptsで緩和可)</span></span></code></pre></div><p>テンプレートの明示的実体化をライブラリから提供することもできます。ただし、それもC++ ABI・型定義・ビルド条件の互換性が必要です。処理系や言語をまたぐ公開APIでは、C ABIの関数と明示したデータ/所有権の契約を検討します。</p><p>根拠: <a href="/study/languages/cpp/templates-and-concepts.html">テンプレート</a>、<a href="/study/runtime/cpp-internals/vtable-and-virtual-calls.html">vtable</a>、<a href="/study/runtime/cpp-internals/symbols-and-linkage.html">ABI</a></p><h2 id="_2-値渡しか参照渡しか" tabindex="-1">2. 値渡しか参照渡しか <a class="header-anchor" href="#_2-値渡しか参照渡しか" aria-label="Permalink to &quot;2. 値渡しか参照渡しか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基本表(引数の受け取り方):</span></span>
<span class="line"><span>  読むだけ+小さい型(目安: ポインタ2個分≒16バイト以下。int, float, Vec2, ポインタ, span)</span></span>
<span class="line"><span>      ──&gt; 値渡し(レジスタに乗る。参照より速いことも)</span></span>
<span class="line"><span>  読むだけ+大きい型(string, vector, 大きいstruct)</span></span>
<span class="line"><span>      ──&gt; const T&amp;</span></span>
<span class="line"><span>  変更する ──&gt; T&amp;(出力が主なら戻り値を検討)</span></span>
<span class="line"><span>  所有権をもらう(保存する)──&gt; 値渡し+std::move / unique_ptr&lt;T&gt;</span></span>
<span class="line"><span>  「無いかもしれない」──&gt; const T* または optional&lt;T&gt;</span></span>
<span class="line"><span>例外: sizeofが小さくてもコピーコンストラクタが重い型は const&amp;。</span></span>
<span class="line"><span>      テンプレート内では汎用に const T&amp;(または転送参照)が無難</span></span></code></pre></div><p>根拠: <a href="/study/languages/cpp/values-pointers-references.html">値と参照</a>、<a href="/study/runtime/cpp-internals/function-calls-and-cpu.html">呼出規約</a>(大きい型はメモリ経由になる)</p><h2 id="_3-unique-ptrかshared-ptrか" tabindex="-1">3. unique_ptrかshared_ptrか <a class="header-anchor" href="#_3-unique-ptrかshared-ptrか" aria-label="Permalink to &quot;3. unique_ptrかshared_ptrか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Q1. まず「ポインタが必要か」: メンバに値で置けるなら置く(ヒープ不要)</span></span>
<span class="line"><span>Q2. ヒープが必要 → 所有者は1つで設計できるか?</span></span>
<span class="line"><span>    → できる ──&gt; unique_ptr(既定。9割はこれ)</span></span>
<span class="line"><span>    → 本当に複数の所有者が寿命に関与する(共有アセット等)──&gt; shared_ptr+循環はweak_ptr</span></span>
<span class="line"><span>Q3. 「所有はしないが、相手が先に死ぬかも」──&gt; weak_ptr(shared管理下)/世代ハンドル(大量オブジェクト)</span></span>
<span class="line"><span>危険信号: 「とりあえずshared」「どこで解放されるか分からないからshared」</span></span>
<span class="line"><span>          → 所有設計の放棄。unique+借用で書き直せないか先に検討</span></span></code></pre></div><p>根拠: <a href="/study/languages/cpp/smart-pointers.html">スマートポインタ</a>、<a href="/study/runtime/memory/ownership-and-borrowing.html">所有権</a></p><h2 id="_4-配列かvectorか" tabindex="-1">4. 配列かvectorか <a class="header-anchor" href="#_4-配列かvectorか" aria-label="Permalink to &quot;4. 配列かvectorか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Q1. サイズはコンパイル時に固定か?</span></span>
<span class="line"><span>    → 固定・要素を自身に保持したい ──&gt; std::array(大きい場合は本体の格納先にも注意)</span></span>
<span class="line"><span>    → 実行時に決まる/伸びる ──&gt; std::vector(既定)</span></span>
<span class="line"><span>Q2. vectorで再確保が問題になるか?(ポインタ保持・フレーム中の確保)</span></span>
<span class="line"><span>    → reserve で事前確保 / 固定容量が本質なら array や自作固定容量vector</span></span>
<span class="line"><span>Q3. 生配列を使ってよいのは: C API境界、意図的な低レベル層のみ(理由をコメント)</span></span>
<span class="line"><span>補足: array/vectorの本体の格納先は変数の作り方で決まる。array=必ずスタックではない</span></span>
<span class="line"><span>補足: 「所有しない連続範囲」を渡すだけなら std::span(C++20)</span></span></code></pre></div><p>根拠: <a href="/study/languages/cpp/arrays-and-strings.html">配列と文字列</a>、<a href="/study/languages/cpp/stl.html">STL</a></p><h2 id="_5-構造体かクラスか" tabindex="-1">5. 構造体かクラスか <a class="header-anchor" href="#_5-構造体かクラスか" aria-label="Permalink to &quot;5. 構造体かクラスか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Q1. 「任意のメンバに任意の値を入れても壊れない」か?</span></span>
<span class="line"><span>    → 壊れない(ただのデータの束: Vec3, HitInfo, Desc)──&gt; struct+public</span></span>
<span class="line"><span>    → 壊れる(不変条件がある: HPは0..max、リストの整合)──&gt; class+private+操作関数</span></span>
<span class="line"><span>Q2. 迷ったら: getter/setterを全メンバに生やしたくなった時点でstructに戻す</span></span>
<span class="line"><span>   (それは隠蔽になっていない → [情報隠蔽](../01_design_basics/05_abstraction_encapsulation.md))</span></span></code></pre></div><p>根拠: <a href="/study/languages/cpp/structs-and-classes.html">構造体とクラス</a></p><h2 id="共通のトレードオフ観" tabindex="-1">共通のトレードオフ観 <a class="header-anchor" href="#共通のトレードオフ観" aria-label="Permalink to &quot;共通のトレードオフ観&quot;">​</a></h2><p>5つの選択はすべて「<strong>自由度と引き換えに何かを固定する</strong>」判断です: テンプレートは型を、値は独立性を、uniqueは所有者を、arrayはサイズを、structは公開を固定する。<strong>固定できるものを固定するほどコードは速く・安全になる</strong>(コンパイラに証明材料を与える)——迷ったら「より多く固定する側」に倒し、要求が現れたら緩める、がC++の基本戦略です。</p><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>テンプレートが使えない(仮想関数必須の)状況を2つ挙げてください。</li><li>「小さい型は値渡しの方が速いことがある」理由は?</li><li>「とりあえずshared_ptr」が危険信号である理由は?</li></ol><hr><p>前: <a href="/study/design/decisions/events-di-singleton.html">イベント・DI・Singletonの判断</a> | <a href="/study/design/decisions/">カテゴリ目次</a> | 次: <a href="/study/design/decisions/optimize-or-refactor.html">最適化・リファクタリングの判断</a></p>`,23)])])}const g=s(t,[["render",i]]);export{u as __pageData,g as default};
